const LANE = 'harare';
// persistent context with fallback to memory if no 'file' store is configured
const pget = (k, d) => { try { const v = flow.get(k, 'file'); return v === undefined ? d : v; } catch (e) { const v = flow.get(k); return v === undefined ? d : v; } };
const pset = (k, v) => { try { flow.set(k, v, 'file'); } catch (e) { flow.set(k, v); } };
// =============================================================================
// VALIDATE & FILTER. Input contract (same for the simulator and, later, MQTT):
//   { "sensor_id": "harare-water-01", "ts": "2026-10-10T12:00:00Z",
//     "readings": { "pressure": 3.1, "flow_rate": 12.4, "level": 71 } }
// Output 1: clean packet. Output 2: rejected packet with a reason.
// =============================================================================
const stats = flow.get('stats:' + LANE) || { ok: 0, rejected: 0, duplicates: 0, reasons: {} };
const PHYS = { pressure: [0, 25], flow_rate: [0, 500], level: [0, 100] };   // physically possible, not fault limits
const HOLD_MAX = 100000;

function show() { node.status({ fill: stats.rejected ? 'yellow' : 'green', shape: 'dot', text: LANE + ' | ok ' + stats.ok + ' | rejected ' + stats.rejected + ' | dup ' + stats.duplicates }); }

function handle(msg) {
  const ref = global.get('reference');
  const reject = (reason, detail) => {
    stats.rejected++; stats.reasons[reason] = (stats.reasons[reason] || 0) + 1;
    flow.set('stats:' + LANE, stats); show();
    return [null, { payload: { reason, detail, packet: String(typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload)).slice(0, 200) } }];
  };
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return reject('bad_json'); } }
if (!p || typeof p !== 'object' || Array.isArray(p)) return reject('bad_shape');
if (!ref) return reject('no_reference_data');
if (typeof p.sensor_id !== 'string' || !ref.sensors[p.sensor_id]) return reject('unknown_sensor', p.sensor_id);
const s = ref.sensors[p.sensor_id];
if (!s.active) return reject('inactive_sensor', p.sensor_id);
if (typeof msg.topic === 'string' && msg.topic.startsWith('hre/telemetry/')) {   // hre/telemetry/<municipality>/<sensor_id>
  const parts = msg.topic.split('/');
  if (parts.length !== 4) return reject('bad_topic', msg.topic);
  if (parts[3] !== p.sensor_id) return reject('topic_sensor_mismatch', msg.topic);
  if (s.muni && parts[2] !== s.muni) return reject('topic_municipality_mismatch', msg.topic);
}
if (!p.readings || typeof p.readings !== 'object') return reject('no_readings');

let ts = Date.now();
if (p.ts !== undefined) ts = typeof p.ts === 'number' ? (p.ts < 1e12 ? p.ts * 1000 : p.ts) : Date.parse(p.ts);
if (!Number.isFinite(ts)) return reject('bad_timestamp');
if (ts > Date.now() + 5 * 60000) return reject('timestamp_in_future', p.ts);
if (ts < Date.now() - 30 * 86400000) return reject('timestamp_too_old', p.ts);
ts = Math.round(ts / 1000) * 1000;

const seen = context.get('seen') || new Set();
const allowed = ref.baseline[s.type] || {};
const out = [], dropped = [];
for (const [metric, raw] of Object.entries(p.readings)) {
  if (!allowed[metric]) { dropped.push('unknown_metric'); continue; }
  const v = (typeof raw === 'string' && raw.trim() !== '') ? Number(raw) : raw;
  if (typeof v !== 'number' || !Number.isFinite(v)) { dropped.push('not_numeric'); continue; }
  const [lo, hi] = PHYS[metric] || [-Infinity, Infinity];
  if (v < lo || v > hi) { dropped.push('implausible_value'); continue; }
  const key = p.sensor_id + '|' + metric + '|' + ts;
  if (seen.has(key)) { stats.duplicates++; dropped.push('duplicate'); continue; }
  seen.add(key);
  if (seen.size > 5000) seen.delete(seen.values().next().value);
  out.push({ metric, value: Math.round(v * 1000) / 1000 });
}
context.set('seen', seen);
if (!out.length) return reject(dropped[0] || 'no_valid_readings', p.sensor_id);

const ls = pget('lastSeen', {});
ls[p.sensor_id] = Math.max(ls[p.sensor_id] || 0, ts);
pset('lastSeen', ls);

stats.ok++; flow.set('stats:' + LANE, stats); show();
return [{ payload: { sensor_id: p.sensor_id, ts: new Date(ts).toISOString(), sensor: s, readings: out, arrived: new Date(msg._arrived || Date.now()).toISOString(), trigger: ['schedule', 'threshold', 'recovery'].includes(p.trigger) ? p.trigger : 'schedule' } }, null];
}

// Reference data (sensors + baseline) may not be loaded for a moment after a restart, exactly when
// the broker delivers the backlog queued while we were down. Hold those packets, never drop them.
if (msg.topic === 'release') {
  const held = context.get('held') || [];
  context.set('held', []);
  const v = [], r = [];
  for (const m of held) { const o = handle(m); if (o[0]) v.push(o[0]); if (o[1]) r.push(o[1]); }
  if (held.length) node.log('reference data ready: released ' + held.length + ' held packet(s)');
  return [v.length ? v : null, r.length ? r : null];
}
msg._arrived = Date.now();                                   // when the packet reached the edge (kept while held)
if (!global.get('reference')) {
  const held = context.get('held') || [];
  if (held.length < HOLD_MAX) held.push({ topic: msg.topic, payload: msg.payload, _arrived: msg._arrived });
  else node.warn('hold buffer full: dropping packets until reference data loads');
  context.set('held', held);
  node.status({ fill: 'yellow', shape: 'ring', text: 'holding ' + held.length + ' packet(s) until reference data loads' });
  return null;
}
return handle(msg);

// persistent context with fallback to memory if no 'file' store is configured
const pget = (k, d) => { try { const v = flow.get(k, 'file'); return v === undefined ? d : v; } catch (e) { const v = flow.get(k); return v === undefined ? d : v; } };
const pset = (k, v) => { try { flow.set(k, v, 'file'); } catch (e) { flow.set(k, v); } };// =============================================================================
// EVALUATE: build telemetry rows and compare each reading with the cached baseline.
// Runs at the edge, so faults are detected even while the uplink is down.
//   ok -> warning (after WARN_CONFIRM consecutive readings) -> critical -> cleared
// Critical alerts fire on the FIRST reading. One alert per state change, never per reading.
// The fault type is diagnosed from the PATTERN across the packet's metrics, not from one metric:
//   water : pressure low + flow high = leak (burst if both critical) | both low = supply_loss
//           pressure low = low_pressure | pressure high = high_pressure | level = reservoir_low/high
//   sewer : level high + flow low = blockage | level high + flow high = overflow
//           level high alone = surcharge (warning) or overflow (critical) | flow high = infiltration
// If the picture changes while a fault is open (e.g. low_pressure becomes a leak), the old type is
// closed with a 'cleared' alert and the new one opened, so open faults never show stale types.
// =============================================================================
const ref = global.get('reference');
const p = msg.payload, s = p.sensor;
const WARN_CONFIRM = Number(env.get('WARN_CONFIRM')) || 2;
const states = pget('alertState', {});
const rows = [];

const classify = (v, b) => v < b.cmin ? ['critical', 'low'] : v > b.cmax ? ['critical', 'high']
                         : v < b.nmin ? ['warning', 'low'] : v > b.nmax ? ['warning', 'high'] : ['ok', null];
const lv = {};
for (const r of p.readings) {
  const b = ref.baseline[s.type] && ref.baseline[s.type][r.metric];
  if (b) { const [level, dir] = classify(r.value, b); lv[r.metric] = { level, dir }; }
}
const out = (m, d) => !!lv[m] && lv[m].level !== 'ok' && lv[m].dir === d;     // metric outside normal in direction d

function diagnose(metric) {
  const d = lv[metric].dir;
  if (s.type === 'water') {
    if (metric === 'level') return d === 'low' ? 'reservoir_low' : 'reservoir_high';
    if (metric === 'pressure' && d === 'high') return 'high_pressure';
    const pLow = out('pressure', 'low'), fHigh = out('flow_rate', 'high'), fLow = out('flow_rate', 'low');
    if (pLow && fHigh) return (lv.pressure.level === 'critical' && lv.flow_rate.level === 'critical') ? 'burst' : 'leak';
    if (pLow && fLow) return 'supply_loss';
    if (metric === 'pressure') return 'low_pressure';
    return d === 'high' ? 'high_flow' : 'low_flow';
  }
  const lHigh = out('level', 'high'), fLow = out('flow_rate', 'low'), fHigh = out('flow_rate', 'high');
  if (lHigh && fLow) return 'blockage';
  if (lHigh && fHigh) return 'overflow';
  if (metric === 'level') return d === 'high' ? (lv.level.level === 'critical' ? 'overflow' : 'surcharge') : 'low_level';
  return d === 'high' ? 'infiltration' : 'low_flow';
}

for (const r of p.readings) {
  rows.push({ t: 'telemetry', r: { time: p.ts, sensor_id: p.sensor_id, metric_type: r.metric, value: r.value } });
  if (s.suppressed || !lv[r.metric]) continue;                 // muted sensor: keep the data, raise nothing
  const { level, dir } = lv[r.metric];
  const b = ref.baseline[s.type][r.metric];
  const key = p.sensor_id + '|' + r.metric;
  const st = states[key] || { s: 'ok', n: 0, ft: null };

  let emit = null;
  if (level === 'critical') { if (st.s !== 'critical') emit = 'critical'; st.n = 0; }
  else if (level === 'warning') {
    if (st.s === 'critical') emit = 'warning';                 // improving, still outside normal
    else if (st.s === 'ok') { st.n++; if (st.n >= WARN_CONFIRM) emit = 'warning'; }
  } else { st.n = 0; if (st.s !== 'ok') emit = 'cleared'; }

  if (emit === 'cleared') {
    rows.push({ t: 'alert', r: { time: p.ts, sensor_id: p.sensor_id, source: 'baseline', fault_type: st.ft || 'out_of_range', severity: 'cleared', metric_type: r.metric, value: r.value, message: 'Reading back within normal range' } });
    st.s = 'ok'; st.ft = null;
  } else if (emit) {
    const ft = diagnose(r.metric);
    if (st.s !== 'ok' && st.ft && st.ft !== ft)                // picture changed: close the old type first
      rows.push({ t: 'alert', r: { time: p.ts, sensor_id: p.sensor_id, source: 'baseline', fault_type: st.ft, severity: 'cleared', metric_type: r.metric, value: r.value, message: 'Reclassified as ' + ft } });
    const message = r.metric.replace('_', ' ') + ' ' + r.value + ' ' + (b.unit || '') + ' is ' + (dir === 'low' ? 'below' : 'above') + ' the ' + (emit === 'critical' ? 'critical' : 'normal') + ' limit (' + ft.replace('_', ' ') + ')';
    rows.push({ t: 'alert', r: { time: p.ts, sensor_id: p.sensor_id, source: p.trigger === 'threshold' ? 'sensor' : 'baseline', fault_type: ft, severity: emit, metric_type: r.metric, value: r.value, message } });
    st.s = emit; st.ft = ft;
  }
  states[key] = st;
}
for (const x of rows) x.r.edge_received_at = p.arrived;      // when the packet reached the edge
pset('alertState', states);
node.status({ fill: 'green', shape: 'dot', text: rows.some(x => x.t === 'alert') ? 'alert raised' : 'normal' });
return { topic: 'data', payload: rows };

// =============================================================================
// CLOUD LINK, lane 'harare': this municipality's OWN uplink to the database.
//   topic 'data' : array of {t:'telemetry'|'alert'|'edge_event', r:{row}}, micro-batched (BATCH_MS)
//   topic 'tick' : flush + health check + replay of this lane's spool (every 30 s, or on demand)
// Online  -> insert, one batched statement per table.
// Offline -> append to spool/harare/current.ndjson (one JSON row per line, power-loss safe).
// Restore -> replay oldest first in batches; inserts are idempotent (ON CONFLICT DO NOTHING).
// Every lane has its own pool, spool and up/down state, so one municipality's outage never
// delays another municipality's data.
// =============================================================================
const LANE  = 'harare';
const DIR   = env.get('HRE_DIR') || path.join(os.homedir(), '.node-red', 'hre-edge');
const SPOOL = path.join(DIR, 'spool', LANE);
const CUR   = path.join(SPOOL, 'current.ndjson');
const EDGE  = env.get('EDGE_ID') || 'hre-edge-01';
const BATCH = 500;
const WINDOW_MS = Number(env.get('BATCH_MS')) || 250;
const MAX_SPOOL = (Number(env.get('MAX_SPOOL_MB')) || 200) * 1024 * 1024;
fs.mkdirSync(SPOOL, { recursive: true });

const pool    = global.get('hre_pool:' + LANE);
const UP      = 'uplink_ok:' + LANE;
const simDown = () => global.get('sim_uplink_down:' + LANE) === true || global.get('sim_uplink_down:all') === true;
const iso     = d => new Date(d).toISOString();
const ev      = (type, detail) => ({ t: 'edge_event', r: { time: iso(Date.now()), edge_id: EDGE, event_type: type, municipality: LANE === 'edge' ? null : LANE, ward_id: null, detail: detail ?? null } });

const SQL = {
  telemetry: `INSERT INTO telemetry (time, sensor_id, metric_type, value, edge_received_at, received_at)
    SELECT x.time, x.sensor_id, x.metric_type::metric_type_enum, x.value, x.edge_received_at, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, sensor_id text, metric_type text, value double precision, edge_received_at timestamptz)
    ON CONFLICT DO NOTHING`,
  alert: `INSERT INTO alert (time, sensor_id, source, fault_type, severity, metric_type, value, message, edge_received_at, received_at)
    SELECT x.time, x.sensor_id, x.source, x.fault_type, x.severity, x.metric_type::metric_type_enum, x.value, x.message, x.edge_received_at, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, sensor_id text, source text, fault_type text, severity text, metric_type text, value double precision, message text, edge_received_at timestamptz)
    ON CONFLICT DO NOTHING`,
  fault_label: `INSERT INTO fault_label (time, event, sensor_id, kind, ramp_s, fault_start, fault_until, received_at)
    SELECT x.time, x.event, x.sensor_id, x.kind, x.ramp_s, x.fault_start, x.fault_until, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, event text, sensor_id text, kind text, ramp_s double precision, fault_start timestamptz, fault_until timestamptz)
    ON CONFLICT DO NOTHING`,
  edge_event: `INSERT INTO edge_event (time, edge_id, event_type, municipality, ward_id, detail, received_at)
    SELECT x.time, x.edge_id, x.event_type, x.municipality, x.ward_id, x.detail, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, edge_id text, event_type text, municipality text, ward_id int, detail jsonb)
    ON CONFLICT DO NOTHING`
};

async function send(rows) {
  if (simDown()) throw new Error('simulated uplink down');
  if (!pool) throw new Error('no database pool');
  for (const t of ['telemetry', 'alert', 'edge_event', 'fault_label']) {
    const part = rows.filter(x => x.t === t).map(x => x.r);
    for (let i = 0; i < part.length; i += BATCH)
      await pool.query(SQL[t], [JSON.stringify(part.slice(i, i + BATCH))]);
  }
}

const spoolFiles = () => fs.readdirSync(SPOOL);
const spoolBytes = () => spoolFiles().reduce((n, f) => n + fs.statSync(path.join(SPOOL, f)).size, 0);
const replayFiles = () => spoolFiles().filter(f => f.startsWith('replay-')).sort();
const backlog = () => replayFiles().length > 0 || (fs.existsSync(CUR) && fs.statSync(CUR).size > 0);

function spool(rows) {
  if (spoolBytes() > MAX_SPOOL) {          // disk guard: keep alerts and events, drop telemetry
    const n = rows.length;
    rows = rows.filter(x => x.t !== 'telemetry');
    node.warn(LANE + ': spool full (' + Math.round(MAX_SPOOL / 1048576) + ' MB): dropped ' + (n - rows.length) + ' telemetry rows');
  }
  if (rows.length) fs.appendFileSync(CUR, rows.map(x => JSON.stringify(x)).join('\n') + '\n');
}

function markDown(err) {
  if (global.get(UP) !== false) {
    global.set(UP, false);
    spool([ev('uplink_down', { reason: String((err && err.message) || err).slice(0, 200) })]);
  }
}
function markUp() {
  const was = global.get(UP);
  global.set(UP, true);
  if (was === false) { spool([ev('uplink_up')]); return true; }
  return false;
}

function status() {
  const kb = Math.round(spoolBytes() / 1024);
  if (global.get(UP) === false) node.status({ fill: 'red', shape: 'dot', text: LANE + ': uplink DOWN | spooled ' + kb + ' KB' });
  else if (backlog()) node.status({ fill: 'yellow', shape: 'dot', text: LANE + ': syncing | ' + kb + ' KB queued' });
  else node.status({ fill: 'green', shape: 'dot', text: LANE + ': uplink OK | queue empty' });
}

async function flush() {
  context.set('timer', 0);
  const rows = context.get('buf') || [];
  if (!rows.length) return;
  context.set('buf', []);
  if (!context.get('busy') && !backlog() && global.get(UP) !== false) {
    try { await send(rows); markUp(); status(); return; } catch (e) { markDown(e); }
  }
  spool(rows);
  status();
}

async function replay() {
  if (fs.existsSync(CUR) && fs.statSync(CUR).size > 0)
    fs.renameSync(CUR, path.join(SPOOL, 'replay-' + Date.now() + '.ndjson'));
  let total = 0, files = 0, oldest = null, newest = null;
  const t0 = Date.now();
  for (const f of replayFiles()) {
    const full = path.join(SPOOL, f);
    const rows = [];
    for (const line of fs.readFileSync(full, 'utf8').split('\n')) {
      if (!line.trim()) continue;
      try { rows.push(JSON.parse(line)); } catch (e) { /* torn last line after a power cut: skip */ }
    }
    try { await send(rows); } catch (e) { markDown(e); return false; }
    fs.unlinkSync(full);
    files++; total += rows.length;
    for (const x of rows) if (x.t === 'telemetry' || x.t === 'alert') {
      const tm = x.r.time;
      if (!oldest || tm < oldest) oldest = tm;
      if (!newest || tm > newest) newest = tm;
    }
  }
  if (total > 0) {
    const e = ev('sync_completed', { rows: total, files, oldest, newest, seconds: Math.round((Date.now() - t0) / 1000) });
    try { await send([e]); } catch (err) { spool([e]); }
  }
  return true;
}

if (msg.topic === 'data') {
  const rows = msg.payload;
  if (!Array.isArray(rows) || !rows.length) return null;
  const buf = context.get('buf') || [];
  for (const r of rows) buf.push(r);
  context.set('buf', buf);
  if (buf.length >= BATCH) { await flush(); return null; }
  const t = context.get('timer');
  if (!t || Date.now() - t > 5000) {                 // collect simultaneous packets into one insert
    context.set('timer', Date.now());
    setTimeout(() => flush().catch(e => node.error(LANE + ': ' + e.message)), WINDOW_MS);
  }
  return null;
}

if (msg.topic === 'tick') {
  await flush();
  if (context.get('busy')) return null;
  context.set('busy', true);
  try {
    try {
      if (simDown()) throw new Error('simulated uplink down');
      if (!pool) throw new Error('no database pool');
      await pool.query('SELECT 1');
    } catch (e) { markDown(e); status(); return null; }
    const restored = markUp();
    await replay();
    status();
    return restored ? [null, { topic: 'refresh', payload: 'uplink restored: ' + LANE }] : null;
  } finally {
    context.set('busy', false);
  }
}
return null;

initialize:
const p = new pg.Pool({ max: 3, connectionTimeoutMillis: 5000, idleTimeoutMillis: 30000, query_timeout: 20000 });
p.on('error', e => node.log('pg pool harare: ' + e.message));   // idle connection dropped; the next query reconnects
global.set('hre_pool:harare', p);

finalize:
const p = global.get('hre_pool:harare');
global.set('hre_pool:harare', undefined);
if (p) { p.end().catch(() => {}); }   // On Stop is not async: no await

