  const lHigh = out('level', 'high'), fLow = out('flow_rate', 'low'), fHigh = out('flow_rate', 'high');
  if (lHigh && fLow) return 'blockage';
  if (lHigh && fHigh) return 'overflow';
  if (metric === 'level') return d === 'high' ? (lv.level.level === 'critical' ? 'overflow' : 'surcharge') : 'low_level';
