// CLOUD LINK, lane 'chitungwiza': this municipality's OWN uplink to the database.
//   topic 'data' : array of {t:'telemetry'|'alert'|'edge_event', r:{row}}, micro-batched (BATCH_MS)
//   topic 'tick' : flush + health check + replay of this lane's spool (every 30 s, or on demand)
// Online  -> insert, one batched statement per table.
// Offline -> append to spool/chitungwiza/current.ndjson (one JSON row per line, power-loss safe).
// Restore -> replay oldest first in batches; inserts are idempotent (ON CONFLICT DO NOTHING).
// Every lane has its own pool, spool and up/down state, so one municipality's outage never
// delays another municipality's data.
// =============================================================================
const LANE  = 'chitungwiza';
const DIR   = env.get('HRE_DIR') || path.join(os.homedir(), '.node-red', 'hre-edge');
const SPOOL = path.join(DIR, 'spool', LANE);
const CUR   = path.join(SPOOL, 'current.ndjson');
const EDGE  = env.get('EDGE_ID') || 'hre-edge-01';
const BATCH = 500;
const WINDOW_MS = Number(env.get('BATCH_MS')) || 250;
const MAX_SPOOL = (Number(env.get('MAX_SPOOL_MB')) || 200) * 1024 * 1024;
fs.mkdirSync(SPOOL, { recursive: true });

const pool    = global.get('hre_pool:' + LANE);
const UP      = 'uplink_ok:' + LANE;
const simDown = () => global.get('sim_uplink_down:' + LANE) === true || global.get('sim_uplink_down:all') === true;
const iso     = d => new Date(d).toISOString();
const ev      = (type, detail) => ({ t: 'edge_event', r: { time: iso(Date.now()), edge_id: EDGE, event_type: type, municipality: LANE === 'edge' ? null : LANE, ward_id: null, detail: detail ?? null } });

const SQL = {
  telemetry: `INSERT INTO telemetry (time, sensor_id, metric_type, value, edge_received_at, received_at)
    SELECT x.time, x.sensor_id, x.metric_type::metric_type_enum, x.value, x.edge_received_at, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, sensor_id text, metric_type text, value double precision, edge_received_at timestamptz)
    ON CONFLICT DO NOTHING`,
  alert: `INSERT INTO alert (time, sensor_id, source, fault_type, severity, metric_type, value, message, edge_received_at, received_at)
    SELECT x.time, x.sensor_id, x.source, x.fault_type, x.severity, x.metric_type::metric_type_enum, x.value, x.message, x.edge_received_at, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, sensor_id text, source text, fault_type text, severity text, metric_type text, value double precision, message text, edge_received_at timestamptz)
    ON CONFLICT DO NOTHING`,
  fault_label: `INSERT INTO fault_label (time, event, sensor_id, kind, ramp_s, fault_start, fault_until, received_at)
    SELECT x.time, x.event, x.sensor_id, x.kind, x.ramp_s, x.fault_start, x.fault_until, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, event text, sensor_id text, kind text, ramp_s double precision, fault_start timestamptz, fault_until timestamptz)
    ON CONFLICT DO NOTHING`,
  edge_event: `INSERT INTO edge_event (time, edge_id, event_type, municipality, ward_id, detail, received_at)
    SELECT x.time, x.edge_id, x.event_type, x.municipality, x.ward_id, x.detail, now()
    FROM jsonb_to_recordset($1::jsonb) AS x(time timestamptz, edge_id text, event_type text, municipality text, ward_id int, detail jsonb)
    ON CONFLICT DO NOTHING`
