async function send(rows) {
  if (simDown()) throw new Error('simulated uplink down');
  if (!pool) throw new Error('no database pool');
  for (const t of ['telemetry', 'alert', 'edge_event', 'fault_label']) {
    const part = rows.filter(x => x.t === t).map(x => x.r);
    for (let i = 0; i < part.length; i += BATCH)
      await pool.query(SQL[t], [JSON.stringify(part.slice(i, i + BATCH))]);
  }
}

const spoolFiles = () => fs.readdirSync(SPOOL);
const spoolBytes = () => spoolFiles().reduce((n, f) => n + fs.statSync(path.join(SPOOL, f)).size, 0);
const replayFiles = () => spoolFiles().filter(f => f.startsWith('replay-')).sort();
const backlog = () => replayFiles().length > 0 || (fs.existsSync(CUR) && fs.statSync(CUR).size > 0);

function spool(rows) {
  if (spoolBytes() > MAX_SPOOL) {          // disk guard: keep alerts and events, drop telemetry
    const n = rows.length;
    rows = rows.filter(x => x.t !== 'telemetry');
    node.warn(LANE + ': spool full (' + Math.round(MAX_SPOOL / 1048576) + ' MB): dropped ' + (n - rows.length) + ' telemetry rows');
  }
  if (rows.length) fs.appendFileSync(CUR, rows.map(x => JSON.stringify(x)).join('\n') + '\n');
}

function markDown(err) {
  if (global.get(UP) !== false) {
    global.set(UP, false);
    spool([ev('uplink_down', { reason: String((err && err.message) || err).slice(0, 200) })]);
  }
}
function markUp() {
  const was = global.get(UP);
  global.set(UP, true);
  if (was === false) { spool([ev('uplink_up')]); return true; }
  return false;
}

function status() {
  const kb = Math.round(spoolBytes() / 1024);
  if (global.get(UP) === false) node.status({ fill: 'red', shape: 'dot', text: LANE + ': uplink DOWN | spooled ' + kb + ' KB' });
  else if (backlog()) node.status({ fill: 'yellow', shape: 'dot', text: LANE + ': syncing | ' + kb + ' KB queued' });
  else node.status({ fill: 'green', shape: 'dot', text: LANE + ': uplink OK | queue empty' });
}

async function flush() {
  context.set('timer', 0);
  const rows = context.get('buf') || [];
  if (!rows.length) return;
  context.set('buf', []);
  if (!context.get('busy') && !backlog() && global.get(UP) !== false) {
    try { await send(rows); markUp(); status(); return; } catch (e) { markDown(e); }
  }
  spool(rows);
  status();
}

async function replay() {
  if (fs.existsSync(CUR) && fs.statSync(CUR).size > 0)
    fs.renameSync(CUR, path.join(SPOOL, 'replay-' + Date.now() + '.ndjson'));
  let total = 0, files = 0, oldest = null, newest = null;
  const t0 = Date.now();
  for (const f of replayFiles()) {
    const full = path.join(SPOOL, f);
    const rows = [];
    for (const line of fs.readFileSync(full, 'utf8').split('\n')) {
      if (!line.trim()) continue;
      try { rows.push(JSON.parse(line)); } catch (e) { /* torn last line after a power cut: skip */ }
    }
    try { await send(rows); } catch (e) { markDown(e); return false; }
    fs.unlinkSync(full);
    files++; total += rows.length;
    for (const x of rows) if (x.t === 'telemetry' || x.t === 'alert') {
      const tm = x.r.time;
      if (!oldest || tm < oldest) oldest = tm;
      if (!newest || tm > newest) newest = tm;
    }
  }
  if (total > 0) {
    const e = ev('sync_completed', { rows: total, files, oldest, newest, seconds: Math.round((Date.now() - t0) / 1000) });
    try { await send([e]); } catch (err) { spool([e]); }
  }
  return true;
}

if (msg.topic === 'data') {
  const rows = msg.payload;
  if (!Array.isArray(rows) || !rows.length) return null;
  const buf = context.get('buf') || [];
  for (const r of rows) buf.push(r);
  context.set('buf', buf);
  if (buf.length >= BATCH) { await flush(); return null; }
  const t = context.get('timer');
  if (!t || Date.now() - t > 5000) {                 // collect simultaneous packets into one insert
    context.set('timer', Date.now());
    setTimeout(() => flush().catch(e => node.error(LANE + ': ' + e.message)), WINDOW_MS);
  }
  return null;
}

if (msg.topic === 'tick') {
  await flush();
  if (context.get('busy')) return null;
  context.set('busy', true);
  try {
    try {
      if (simDown()) throw new Error('simulated uplink down');
      if (!pool) throw new Error('no database pool');
      await pool.query('SELECT 1');
    } catch (e) { markDown(e); status(); return null; }
    const restored = markUp();
    await replay();
    status();
    return restored ? [null, { topic: 'refresh', payload: 'uplink restored: ' + LANE }] : null;
  } finally {
    context.set('busy', false);
  }
}
return null;

