// POWER STATE. Today: manual inject. Later: an MQTT topic (e.g. hre/<site>/power),
// a UPS feed (NUT) or a mains-detect GPIO. Accepts 'on'/'off' or {grid:true|false}.
const EDGE = env.get('EDGE_ID') || 'hre-edge-01';
const v = (msg.payload && typeof msg.payload === 'object') ? msg.payload.grid : msg.payload;
const gridOk = (v === true || v === 'on' || v === 'ok' || v === 1);
const prev = global.get('grid_ok');
global.set('grid_ok', gridOk);
node.status({ fill: gridOk ? 'green' : 'red', shape: 'dot', text: gridOk ? 'grid power OK' : 'ON BATTERY / LOADSHEDDING' });
if (prev === gridOk || (prev === undefined && gridOk)) return null;
return { topic: 'data', payload: [{ t: 'edge_event', r: { time: new Date().toISOString(), edge_id: EDGE, event_type: gridOk ? 'power_restored' : 'power_loss', ward_id: null, detail: { source: msg.topic || 'manual' } } }] };

// persistent context with fallback to memory if no 'file' store is configured
const pget = (k, d) => { try { const v = flow.get(k, 'file'); return v === undefined ? d : v; } catch (e) { const v = flow.get(k); return v === undefined ? d : v; } };
const pset = (k, v) => { try { flow.set(k, v, 'file'); } catch (e) { flow.set(k, v); } };
// =============================================================================
// WATCHDOG (runs every 60 s). Works out WHO is silent and, from the pattern, WHY:
//   one sensor silent                 -> 'offline' alert (device or comms fault)
//   every sensor in a ward silent     -> 'ward_outage_suspected'         (loadshedding)
//   every sensor in a municipality    -> 'municipality_outage_suspected'
//   every sensor in the province      -> 'province_outage_suspected'
// Only the HIGHEST level is announced, so a province outage is one event, not 25.
// A grace period after Node-RED starts avoids false alarms right after a reboot.
// =============================================================================
const ref = global.get('reference');
if (!ref) return null;
const EDGE = env.get('EDGE_ID') || 'hre-edge-01';
const OFFLINE_MS = (Number(env.get('OFFLINE_AFTER_MIN')) || 15) * 60000;
let t0 = context.get('t0');
if (!t0) { t0 = Date.now(); context.set('t0', t0); }
if (Date.now() - t0 < OFFLINE_MS) { node.status({ fill: 'grey', shape: 'ring', text: 'grace period after start' }); return null; }

const now = Date.now(), iso = d => new Date(d).toISOString();
const ls = pget('lastSeen', {}), wd = pget('wdState', {});
const rows = [], wards = {}, munis = {};
let pTotal = 0, pSilent = 0;
let seq = 0;   // +1 ms per event: simultaneous events of one type must not collide on the unique (edge_id, event_type, time) key
const event = (type, wardId, detail) => rows.push({ t: 'edge_event', r: { time: iso(now + seq++), edge_id: EDGE, event_type: type, ward_id: wardId, municipality: (detail && detail.municipality) || null, detail } });

for (const [id, s] of Object.entries(ref.sensors)) {
  if (!s.active || s.suppressed) continue;
  const last = ls[id] ?? t0;
  const silent = now - last > OFFLINE_MS;
  const w = (wards[s.ward_id] ??= { ids: [], silent: 0, muni: s.muni, num: s.ward_number });
  w.ids.push(id); if (silent) w.silent++;
  const m = (munis[s.muni] ??= { ids: 0, silent: 0, wards: new Set() });
  m.ids++; m.wards.add(s.ward_id); if (silent) m.silent++;
  pTotal++; if (silent) pSilent++;
  if (silent && !wd[id]) {
    wd[id] = 1;
    rows.push({ t: 'alert', r: { time: iso(now), sensor_id: id, source: 'watchdog', fault_type: 'offline', severity: 'critical', metric_type: null, value: null, message: 'No data for ' + Math.round((now - last) / 60000) + ' min' } });
  } else if (!silent && wd[id]) {
    delete wd[id];
    rows.push({ t: 'alert', r: { time: iso(last), sensor_id: id, source: 'watchdog', fault_type: 'offline', severity: 'cleared', metric_type: null, value: null, message: 'Sensor reporting again' } });
  }
}

// state per scope: 1 = announced, 2 = silent but covered by a higher-level announcement
function scope(key, cond, parentCond, restoreCond, announceType, restoreType, wardId, detail) {
  const st = wd[key], announce = cond && !parentCond;
  if (cond && !st) { wd[key] = announce ? 1 : 2; if (announce) event(announceType, wardId, detail); }
  else if (st === 2 && announce) { wd[key] = 1; event(announceType, wardId, detail); }
  else if (st && restoreCond) { if (st === 1) event(restoreType, wardId, detail && detail.municipality ? { municipality: detail.municipality } : null); delete wd[key]; }
}

const provCond = pTotal >= 2 && Object.keys(munis).length >= 2 && pSilent === pTotal;
scope('prov', provCond, false, !provCond, 'province_outage_suspected', 'province_restored', null,
  { sensors: pTotal, hint: 'every sensor in the province went silent together (province-wide loadshedding or core network failure)' });

const muniCond = {};
for (const [slug, m] of Object.entries(munis)) {
  muniCond[slug] = m.wards.size >= 2 && m.silent === m.ids;
  scope('muni:' + slug, muniCond[slug], provCond, !muniCond[slug], 'municipality_outage_suspected', 'municipality_restored', null,
    { municipality: slug, sensors: m.ids, hint: 'every sensor in the municipality went silent together (loadshedding)' });
}
for (const [wid, g] of Object.entries(wards)) {
  const cond = g.ids.length >= 2 && g.silent === g.ids.length;
  scope('ward' + wid, cond, provCond || muniCond[g.muni], g.silent === 0, 'ward_outage_suspected', 'ward_restored', Number(wid),
    { municipality: g.muni, ward: g.num, sensors: g.ids, hint: 'all sensors in the ward went silent together (loadshedding pattern)' });
}

pset('wdState', wd);
const flagged = Object.keys(wd).filter(k => /^[a-z]+-(water|sewer)-/.test(k)).length;
const top = wd.prov === 1 ? 'PROVINCE outage' : Object.keys(wd).some(k => k.startsWith('muni:') && wd[k] === 1) ? 'municipality outage' : null;
node.status({ fill: flagged ? 'red' : 'green', shape: 'dot', text: (top ? top + ' | ' : '') + flagged + ' sensor(s) silent' });
for (const r of rows) if (r.t === 'alert') r.r.edge_received_at = iso(now);   // created at the edge
// route every row to the lane that owns it: sensors -> their municipality, province/edge events -> 'edge'
const LANES = ['harare', 'chitungwiza', 'epworth', 'ruwa', 'edge'];
const routed = LANES.map(() => []);
for (const r of rows) {
  const m = r.t === 'alert' ? (ref.sensors[r.r.sensor_id] || {}).muni : r.r.municipality;
  const i = LANES.indexOf(m);
  routed[i < 0 ? LANES.length - 1 : i].push(r);
