p.on('error', e => node.log('pg pool edge: ' + e.message));   // idle connection dropped; the next query reconnects
global.set('hre_pool:edge', p);

finalize:
const p = global.get('hre_pool:edge');
global.set('hre_pool:edge', undefined);
if (p) { p.end().catch(() => {}); }   // On Stop is not async: no await

