// =============================================================================
// FAULT LABELS: ground truth published by the sensor fleet on hre/labels/<municipality>/<sensor_id>.
// Stored in fault_label so detection delay can be measured: first alert minus fault start.
// Goes through the edge lane, so it is spooled and synced like everything else.
// =============================================================================
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || !p.sensor_id || !p.fault_start || !['fault_start', 'fault_end'].includes(p.event)) return null;
const ref = global.get('reference');
if (ref && !ref.sensors[p.sensor_id]) return null;                 // unknown sensor: ignore
node.status({ fill: 'green', shape: 'dot', text: p.event + ': ' + p.sensor_id + ' ' + (p.kind || '') });
return { topic: 'data', payload: [{ t: 'fault_label', r: { time: p.time || p.fault_start, event: p.event, sensor_id: p.sensor_id, kind: String(p.kind || ''), ramp_s: p.ramp_s ?? null, fault_start: p.fault_start, fault_until: p.fault_until ?? null } }] };

// =============================================================================
// UPLINK SWITCH (testing): cut or restore ONE municipality's uplink to the cloud while its
// sensors keep running. Each lane then spools to its own JSON file and syncs on restore.
//   payload {"lane":"ruwa","down":true,"cause":"network"|"loadshedding"}   cause=loadshedding also logs
//          power_loss / power_restored for that municipality (sensors stay up on battery)
//   payload {"lane":"harare","flap":{"cycles":3,"down_s":20,"up_s":10}}     intermittent service
//   lane = harare | chitungwiza | epworth | ruwa | edge | all
// Also driven by MQTT: hre/sim/uplink/<lane> (same payload) so test scripts can use it.
// =============================================================================
const EDGE = env.get('EDGE_ID') || 'hre-edge-01';
const LANES = ['harare', 'chitungwiza', 'epworth', 'ruwa', 'edge'];
let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;
const lane = p.lane || (typeof msg.topic === 'string' && msg.topic.startsWith('hre/sim/uplink/') ? msg.topic.split('/')[3] : null);
if (!lane) return null;
const targets = lane === 'all' ? LANES : [lane];

function setLane(l, down, cause) {
  const i = LANES.indexOf(l);
  if (i < 0) return;
  const was = global.get('sim_uplink_down:' + l) === true;
  global.set('sim_uplink_down:' + l, down);
  const msgs = [];
  if (was !== down && cause === 'loadshedding' && l !== 'edge')
    msgs.push({ topic: 'data', payload: [{ t: 'edge_event', r: { time: new Date().toISOString(), edge_id: EDGE, event_type: down ? 'power_loss' : 'power_restored', municipality: l, ward_id: null, detail: { cause: 'loadshedding', effect: 'uplink and gateway without mains power; sensors keep running on battery' } } }] });
  msgs.push({ topic: 'tick' });                        // make the lane notice right now
  const out = LANES.map(() => null);
  out[i] = msgs;
  node.send(out);
}

if (p.flap) {
  const f = Object.assign({ cycles: 3, down_s: 20, up_s: 10 }, p.flap);
  let n = 0;
  const step = () => {
    if (n >= f.cycles * 2) return;
    const down = n % 2 === 0;
    targets.forEach(l => setLane(l, down, 'network'));
    n++;
    setTimeout(step, (down ? f.down_s : f.up_s) * 1000);
  };
  step();
  node.status({ fill: 'yellow', text: 'flapping ' + targets.join(',') + ': ' + f.cycles + 'x ' + f.down_s + 's down / ' + f.up_s + 's up' });
  return null;
}
targets.forEach(l => setLane(l, p.down === true, p.cause));
node.status({ fill: p.down === true ? 'red' : 'green', text: targets.join(',') + ' uplink ' + (p.down === true ? 'DOWN' : 'UP') + (p.cause ? ' (' + p.cause + ')' : '') });
return null;

const DIR = env.get('HRE_DIR') || path.join(os.homedir(), '.node-red', 'hre-edge');
// REFERENCE DATA: sensors + baseline from the database, cached to disk so the edge
// can still validate readings and detect faults while the uplink is down.
const FILE = path.join(DIR, 'reference.json');
fs.mkdirSync(DIR, { recursive: true });
const pool = global.get('hre_pool:ref');
let ref = null, source = 'database';
try {
  if (global.get('sim_uplink_down:all') === true) throw new Error('simulated uplink down');
  if (!pool) throw new Error('no database pool');
  const s = await pool.query('SELECT s.sensor_id, s.sensor_type, s.ward_id, w.ward_number, m.slug AS muni, s.active, s.suppressed FROM sensor s JOIN ward w ON w.ward_id = s.ward_id JOIN municipality m ON m.municipality_id = w.municipality_id');
  const b = await pool.query('SELECT sensor_type, metric_type::text AS metric_type, unit, normal_min, normal_max, crit_min, crit_max FROM baseline');
  ref = { loaded: new Date().toISOString(), sensors: {}, baseline: {} };
  for (const r of s.rows) ref.sensors[r.sensor_id] = { type: r.sensor_type, ward_id: r.ward_id, ward_number: r.ward_number, muni: r.muni, active: r.active !== false, suppressed: r.suppressed === true };
  for (const r of b.rows) (ref.baseline[r.sensor_type] ??= {})[r.metric_type] = { unit: r.unit, nmin: r.normal_min, nmax: r.normal_max, cmin: r.crit_min, cmax: r.crit_max };
  fs.writeFileSync(FILE + '.tmp', JSON.stringify(ref));
  fs.renameSync(FILE + '.tmp', FILE);
} catch (e) {
  source = 'cached file';
  try { ref = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e2) { ref = null; }
  node.warn('reference data: database unavailable (' + e.message + '), using ' + (ref ? 'cached file' : 'nothing'));
}
if (ref) {
  global.set('reference', ref);
  node.status({ fill: 'green', shape: 'dot', text: Object.keys(ref.sensors).length + ' sensors | ' + source });
} else {
  node.status({ fill: 'red', shape: 'ring', text: 'no reference data' });
}
return ref ? { topic: 'release' } : null;   // tells VALIDATE to release any packets it was holding

initialize:
// Load the cached reference data synchronously at start, before the broker can deliver the backlog.
const DIR = env.get('HRE_DIR') || path.join(os.homedir(), '.node-red', 'hre-edge');
try { global.set('reference', JSON.parse(fs.readFileSync(path.join(DIR, 'reference.json'), 'utf8'))); }
catch (e) { /* first run: no cache yet */ }

const rp = new pg.Pool({ max: 2, connectionTimeoutMillis: 5000, idleTimeoutMillis: 30000, query_timeout: 20000 });
rp.on('error', e => node.log('pg pool ref: ' + e.message));
global.set('hre_pool:ref', rp);

finalize:
const p = global.get('hre_pool:ref');
global.set('hre_pool:ref', undefined);
if (p) { p.end().catch(() => {}); }

