// =============================================================================
// CONTROL PANEL (testing only). Real telemetry now comes from the Python nodes over MQTT.
//   power         loadshedding: retained hre/sim/power/... switches the Python nodes obey
//   restore_power delete every switch (same effect as hre_control.py --action power-on)
//   clear_faults  live (NOT retained) "clear" for every node
//   bad           malformed packets to prove the validator rejects them
// Node-RED never reads the power topics: it has to DETECT an outage from the silence.
// =============================================================================
const ref = global.get('reference');
const p = msg.payload || {};
const cmd = p.cmd;
const ctl = [];
const ctlMsg = (topic, payload, retain) => ctl.push({ topic, payload, qos: 1, retain: !!retain });
const out2 = text => { node.status({ text }); return [null, ctl.length ? ctl : null]; };

if (cmd === 'clear_faults') {
  ctlMsg('hre/sim/fault/all', JSON.stringify({ kind: 'clear' }), false);
  return out2('clear sent to every node');
}
if (cmd === 'power') {
  const key = p.scope === 'province' ? 'all' : p.scope === 'municipality' ? p.municipality + '/all' : p.municipality + '/' + p.ward;
  ctlMsg('hre/sim/power/' + key, JSON.stringify({ grid: false }), true);
  return out2('power OFF: ' + key);
}
if (cmd === 'restore_power') {
  if (!ref) { node.warn('control panel: reference data not loaded yet'); return null; }
  const keys = new Set(['all']);
  for (const s of Object.values(ref.sensors)) { keys.add(s.muni + '/all'); keys.add(s.muni + '/' + s.ward_number); }
  for (const k of keys) ctlMsg('hre/sim/power/' + k, '', true);
  return out2('power restored everywhere (' + keys.size + ' switches cleared)');
}
if (cmd === 'bad') {
  const now = new Date().toISOString();
  return [[
    { payload: 'this is not json' },
    { payload: { sensor_id: 'nope-water-99', ts: now, readings: { pressure: 3 } } },
    { payload: { sensor_id: 'harare-water-01', ts: now, readings: { pressure: 'abc' } } },
    { payload: { sensor_id: 'harare-water-01', ts: new Date(Date.now() + 3600e3).toISOString(), readings: { pressure: 3 } } },
    { payload: { sensor_id: 'harare-water-01', ts: now, readings: { pressure: 999 } } },
    { payload: { sensor_id: 'harare-water-01', ts: now, readings: { temperature: 21 } } },
    { topic: 'hre/telemetry/ruwa/harare-water-01', payload: { sensor_id: 'harare-water-01', ts: now, readings: { pressure: 3 } } }
  ], null];
}
return null;
